let deskAgendaView='today';
function renderHome(){renderWorkdesk(false)}
function deskEmpty(title,copy,action='new-event',label='Agendar un encuentro'){
  return `<div class="desk-empty"><span class="desk-empty-mark" aria-hidden="true">↗</span><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action?button(label,action,'plus'):''}</div>`;
}
function deskAgendaMarkup(){
  const date=today(),events=state.events.filter(e=>e.status==='Pendiente'&&e.date&&
    (deskAgendaView==='overdue'?e.date.slice(0,10)<date:deskAgendaView==='next'?e.date.slice(0,10)>date:e.date.slice(0,10)===date)).sort((a,b)=>a.date.localeCompare(b.date));
  if(!events.length){const text=deskAgendaView==='overdue'?['Sin actividades de días anteriores.','Los seguimientos pendientes anteriores a hoy aparecerán acá.']:deskAgendaView==='next'?['El próximo encuentro empieza acá.','Reservá un momento para volver a conversar con tus clientes.']:['Hoy tenés espacio.','Prepará una visita o agendá tu próxima conversación.'];return deskEmpty(...text)}
  return events.slice(0,6).map(e=>`<article class="desk-appointment ${deskAgendaView==='overdue'?'is-overdue':''}"><div class="desk-appointment-time"><span>${esc(time(e.date))}</span><small>${deskAgendaView==='today'?'Hoy':esc(shortDate(e.date))}</small></div><div class="desk-appointment-body"><span class="desk-category">${esc(e.type||'Encuentro')}</span><h3>${esc(e.title)}</h3><p>${esc(client(e.clientId).name||'Actividad sin cliente vinculado')}${e.propertyId?' · '+esc(property(e.propertyId).zone||property(e.propertyId).title||'Inmueble'):''}</p>${isAdmin()?`<small>${esc(advisorName(e.advisorId))}</small>`:''}</div>${button('Abrir','edit-event','arrow','',`data-id="${esc(e.id)}"`)}</article>`).join('')+(events.length>6?'<a class="desk-more" href="#agenda">Continuar en la agenda →</a>':'');
}
function paintDeskAgenda(){
  const root=$('#deskAgenda');if(!root)return;root.innerHTML=deskAgendaMarkup();
  $$('[data-desk-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.deskView===deskAgendaView)));
}
function deskDrafts(){
  const drafts=state.visits.filter(v=>v.status==='Borrador').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
  return drafts.length?drafts.slice(0,3).map(v=>`<a class="desk-draft" href="#visitas/${encodeURIComponent(v.id)}"><span class="desk-draft-icon">${icon('file')}</span><div><h3>${esc(client(v.clientId).name||'Visita por completar')}</h3><p>${esc(property(v.propertyId).title||'Hoja de visita en preparación')}</p><small>${esc(shortDate(v.date))}${isAdmin()?' · '+esc(v.advisor||advisorName(v.advisorId)):''}</small></div><span aria-hidden="true">↗</span></a>`).join(''):'<p class="desk-note-empty">Las hojas guardadas como borrador aparecerán acá para revisar los acuerdos antes de confirmarlos.</p>';
}
function deskPeople(central){
  if(central){
    const unassigned=state.clients.filter(c=>!c.advisorId);
    return `<section class="desk-people"><div class="desk-section-head"><h2>Repartir el próximo paso</h2><a href="#asignaciones">Asignaciones ↗</a></div>${unassigned.length?unassigned.slice(0,4).map(c=>`<div class="desk-person"><span class="desk-person-initial">${esc(initials(c.name))}</span><div><a href="#clientes/${encodeURIComponent(c.id)}">${esc(c.name)}</a><p>Elegí quién acompañará a este cliente.</p></div>${button('Asignar','assign-client','arrow','',`data-id="${esc(c.id)}"`)}</div>`).join(''):(state.clients.length?'<p class="desk-quiet">Cada cliente registrado tiene un asesor asignado.</p>':'<p class="desk-quiet">Registrá un cliente y elegí quién lo va a acompañar.</p>')}<div class="desk-team-line"><span>Tu equipo</span>${activeAdvisors().slice(0,4).map(u=>`<button type="button" data-action="edit-user" data-id="${esc(u.id)}">${esc(u.name)}</button>`).join('')||'<a href="#equipo">Preparar los accesos →</a>'}</div></section>`;
  }
  const conversations=state.operations.filter(o=>!['Cierre','Descartada'].includes(o.stage));
  return `<section class="desk-people"><div class="desk-section-head"><h2>Conversaciones abiertas</h2><a href="#operaciones">Ver operaciones ↗</a></div>${conversations.length?conversations.slice(0,4).map(o=>`<div class="desk-person"><span class="desk-person-initial">${esc(initials(client(o.clientId).name))}</span><div><h3>${esc(client(o.clientId).name||'Cliente')}</h3><p>${esc(property(o.propertyId).title||'Inmueble')} · ${esc(o.stage)}</p></div>${button('Retomar','edit-operation','arrow','',`data-id="${esc(o.id)}"`)}</div>`).join(''):'<p class="desk-quiet">Al iniciar una operación, vas a encontrar acá la conversación para continuarla.</p>'}<a class="desk-more" href="#clientes">Volver a mis clientes →</a></section>`;
}
function renderWorkdesk(central=false){
  const available=state.properties.filter(p=>p.status==='Disponible'),name=config.user?.split(' ')[0]||'Tu espacio';
  $('#main').innerHTML=`<div class="workdesk"><div class="desk-masthead"><span>${central?'LA JORNADA DEL EQUIPO':'LA JORNADA DE '+esc(name.toUpperCase())}</span><time datetime="${today()}">${esc(longDate(today()))}</time></div><header class="desk-intro"><div><h1>La jornada<span>.</span></h1><p>${central?'Prepará los encuentros. Acompañá a las personas. Hacé avanzar cada conversación.':'Tus encuentros, tus conversaciones y el espacio para lo que sigue.'}</p></div>${button('Grabar una visita','new-visit','mic','desk-record')}</header>${demoNotice()}<div class="desk-layout"><div class="desk-main"><section class="desk-agenda"><div class="desk-section-head"><div><span class="desk-kicker">ENCUENTROS Y SEGUIMIENTOS</span><h2>En agenda</h2></div><button type="button" class="desk-add" data-action="new-event" aria-label="Agendar actividad">${icon('plus')}</button></div><div class="desk-tabs" role="group" aria-label="Filtrar agenda"><button type="button" data-desk-view="today" aria-pressed="${deskAgendaView==='today'}">Hoy</button><button type="button" data-desk-view="next" aria-pressed="${deskAgendaView==='next'}">Próximos</button><button type="button" data-desk-view="overdue" aria-pressed="${deskAgendaView==='overdue'}">Atrasados</button></div><div id="deskAgenda" class="desk-agenda-list" aria-live="polite">${deskAgendaMarkup()}</div><a class="desk-agenda-link" href="#agenda">Abrir mi agenda completa ${icon('arrow')}</a></section>${deskPeople(central)}</div><aside class="desk-side"><section class="desk-notebook"><div class="desk-note-top"><span>DESPUÉS DE LA VISITA</span>${icon('note')}</div><h2>Lo conversado<br>merece un próximo paso.</h2><p class="desk-note-intro">Hojas por revisar antes de confirmar.</p><div>${deskDrafts()}</div><a class="desk-note-link" href="#visitas">Ir a las hojas de visita ↗</a></section><section class="desk-tools"><h2>${central?'Organizar el equipo':'Preparar mi próxima visita'}</h2>${central?button('Crear acceso de asesor','new-user','people')+button('Asignar una cartera','goto-assignments','link'):button('Registrar un cliente','new-client','people')}<a href="#coincidencias">${icon('spark')}Buscar un inmueble para un cliente ${icon('arrow')}</a>${canManageProperties()?button('Agregar un inmueble','new-property','building'):''}${central&&(!config.marketplace||config.profile?.platformAdmin)&&!state.clients.length?button('Explorar datos de ejemplo','demo','spark'):''}<a href="/explorar" target="_blank" rel="noopener">${icon('pin')}Explorar el mapa público ${icon('arrow')}</a></section></aside></div><section class="desk-catalog"><div class="desk-section-head"><div><span class="desk-kicker">PARA EL PRÓXIMO ENCUENTRO</span><h2>Inmuebles a mano</h2></div><a href="#inmuebles">Abrir cartera ↗</a></div>${available.length?`<div class="desk-property-strip">${available.slice(0,4).map(p=>`<a class="desk-property" href="#inmuebles/${encodeURIComponent(p.id)}"><div class="desk-property-art">${artwork(p)}</div><div><small>${esc(p.operation)} · ${esc(p.zone||'Zona por completar')}</small><h3>${esc(p.title)}</h3><p>${money(p.price,p.currency)}${p.operation==='Alquiler'?' / mes':''}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</div>`:deskEmpty('Cada encuentro necesita un lugar.',canManageProperties()?'Agregá un inmueble para preparar tus próximas visitas.':'Cuando te asignen inmuebles disponibles, los vas a encontrar acá.',canManageProperties()?'new-property':'', 'Agregar un inmueble')}</section></div>`;
}
document.addEventListener('click',event=>{
  const tab=event.target.closest('[data-desk-view]');
  if(!tab||route!=='inicio'||!['today','next','overdue'].includes(tab.dataset.deskView))return;
  deskAgendaView=tab.dataset.deskView;paintDeskAgenda();
});

function stat(label,value,ico,note){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span>${icon(ico)}</div><div class="stat-value mono">${value}</div><div class="stat-note">${note}</div></div>`}

function renderClients(){ $('#main').innerHTML=heading('CADA PERSONA, SU HISTORIA','Clientes','Conocé lo que buscan. Recordá lo que importa.',button('Nuevo cliente','new-client','plus','primary'))+demoNotice()+`<div class="filters"><div class="search">${icon('search')}<input id="clientSearch" placeholder="Buscar por nombre, zona o necesidad…" aria-label="Buscar clientes"></div><select id="clientRole" aria-label="Filtrar clientes"><option value="">Todos los clientes</option>${['Comprador','Propietario','Inquilino','Inversor'].map(r=>`<option>${r}</option>`).join('')}</select></div><section class="card table-wrap" id="clientsTable"></section>`;filterClients() }
function filterClients(){const term=($('#clientSearch')?.value||'').toLowerCase();const role=$('#clientRole')?.value;const cs=state.clients.filter(c=>(!role||c.role===role)&&[c.name,c.zone,...c.zones||[],...c.needs||[]].join(' ').toLowerCase().includes(term));$('#clientsTable').innerHTML=cs.length?`<table><thead><tr><th>CLIENTE</th><th>BUSCA</th><th>PRESUPUESTO</th><th>ZONAS</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><a class="table-person" href="#clientes/${esc(c.id)}"><span class="avatar">${esc(initials(c.name))}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.role)}${c.demo?' · Demo':''}</small></span></a></td><td>${esc(c.propertyType||c.intent||'Por definir')}</td><td>${c.budget?money(c.budget,c.currency):'Por definir'}</td><td>${esc((c.zones||[]).join(', ')||'Por definir')}</td><td><a class="link" href="#clientes/${esc(c.id)}">Ver ficha ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table>`:empty('No encontramos clientes','Probá con otra búsqueda o agregá tu primer cliente.','new-client','Nuevo cliente')}
function clientVisits(c){return state.visits.filter(v=>v.clientId===c.id).sort((a,b)=>b.date.localeCompare(a.date))}
function renderClient(id){const c=client(id);if(!c.id)return missing();const vs=clientVisits(c),last=vs.find(v=>v.status==='Confirmada');$('#main').innerHTML=`<a class="link back" href="#clientes">${icon('back')} Volver a clientes</a>`+heading('EXPEDIENTE DEL CLIENTE',esc(c.name),`${esc(c.role)}${c.demo?' · Datos de ejemplo':''}`,button('Editar ficha','edit-client','note','',`data-id="${esc(id)}"`)+(isAdmin()?button('Asignar asesor','assign-client','people','',`data-id="${esc(id)}"`):'')+button('Nueva visita','new-visit','mic','primary',`data-client="${esc(id)}"`))+`<div class="detail-grid"><div><section class="card"><div class="card-header"><h2>Lo que está buscando</h2>${badge(c.intent||c.role)}</div><div class="info-grid">${info('Asesor responsable',advisorName(c.advisorId))}${info('Presupuesto',c.budget?money(c.budget,c.currency):'Por definir')}${info('Tipo de inmueble',c.propertyType||'Por definir')}${info('Zonas de interés',(c.zones||[]).join(', ')||'Por definir')}${info('Dormitorios',c.bedrooms||'Por definir')}${info('Teléfono',c.phone||'Sin registrar')}${info('Correo',c.email||'Sin registrar')}</div><div class="section-label">Necesidades y preferencias</div><div class="chips">${(c.needs||[]).map(n=>`<span class="chip">${esc(n)}</span>`).join('')||'<span class="subhead">Todavía no hay preferencias registradas.</span>'}</div>${c.notes?'<p class="body-copy">'+esc(c.notes)+'</p>':''}${last?`<div class="contact-brief"><div class="eyebrow">ANTES DEL PRÓXIMO CONTACTO</div><p>${esc(last.sheet?.summary||'Última visita registrada el '+shortDate(last.date))}</p>${last.sheet?.nextStep?'<p style="margin-top:10px"><strong>Próximo paso:</strong> '+esc(last.sheet.nextStep)+'</p>':''}</div>`:''}<div class="suggested-actions">${button('Ver coincidencias','goto-matches','spark','soft',`data-id="${esc(id)}"`)}${button('Preparar WhatsApp','whatsapp','phone','',`data-id="${esc(id)}"`)}</div></section><section class="card"><div class="card-header"><h2>Conversaciones y visitas</h2><span class="badge">${vs.length} visitas</span></div>${vs.length?vs.map(visitRow).join(''):empty('Una historia por comenzar','Las hojas de visita de este cliente aparecerán acá.')}<div class="ask-box"><h3>Preguntale a su historial</h3><p class="subhead" style="margin-top:7px">Consultá las hojas confirmadas: qué le gustó, qué descartó o qué quedó pendiente.</p><div class="ask-input"><input id="historyQuestion" placeholder="¿Qué objeciones tuvo en sus visitas?" aria-label="Pregunta sobre el historial">${button('Preguntar','ask','spark','primary',`data-id="${esc(id)}"`)}</div><div id="historyAnswer"></div></div></section></div><div><section class="card"><div class="card-header"><h2>Documentación</h2>${button('Agregar','upload','upload','small',`data-id="${esc(id)}"`)}</div>${fileList(id)}</section><section class="card"><div class="card-header"><h2>Operaciones vinculadas</h2>${button('Nueva','new-operation','plus','small',`data-client="${esc(id)}"`)}</div>${state.operations.filter(o=>o.clientId===id).map(o=>`<div class="person-row"><div><h3>${esc(property(o.propertyId).title)}</h3><p>${money(o.value,o.currency)}</p></div>${badge(o.stage)}</div>`).join('')||empty('Todavía no hay operaciones','Una relación puede convertirse en una oportunidad.')}</section></div></div>`}
function info(label,value){return `<div class="info-item"><small>${label}</small><strong>${esc(value)}</strong></div>`}

function renderProperties(){ $('#main').innerHTML=heading('CADA ESPACIO, UNA POSIBILIDAD','Inmuebles','Organizá tu cartera y encontrá el próximo lugar para cada cliente.',(canManageProperties()?button('Agregar inmueble','new-property','plus','primary'):''))+demoNotice()+`<div class="filters"><div class="search">${icon('search')}<input id="propertySearch" placeholder="Buscar por título, código o zona…" aria-label="Buscar inmuebles"></div><select id="propertyOperation" aria-label="Filtrar operación"><option value="">Venta y alquiler</option><option>Venta</option><option>Alquiler</option></select><select id="propertyStatus" aria-label="Filtrar estado"><option value="">Todos los estados</option><option>Disponible</option><option>Reservado</option><option>Vendido</option><option>Alquilado</option><option>Pausado</option></select></div><div class="filter-result" id="propertyCount"></div><div class="private-map-actions"><button class="btn" type="button" data-action="properties-list">Lista</button><button class="btn" type="button" data-action="properties-map">Mapa</button></div><div id="privatePropertyMap" class="private-property-map" hidden></div><div class="properties-grid" id="propertyGrid"></div>`;filterProperties() }
function filterProperties(){const t=($('#propertySearch')?.value||'').toLowerCase(),op=$('#propertyOperation')?.value,st=$('#propertyStatus')?.value;const ps=state.properties.filter(p=>(!op||p.operation===op)&&(!st||p.status===st)&&[p.title,p.code,p.zone,p.description].join(' ').toLowerCase().includes(t));$('#propertyCount').textContent=ps.length+' inmuebles en tu cartera';$('#propertyGrid').innerHTML=ps.length?ps.map(propertyCard).join(''):empty('Un espacio para tu primera propiedad','Agregá características, precio, propietario y documentos.','new-property','Agregar inmueble');if(typeof paintPrivatePropertyMap==='function')paintPrivatePropertyMap(ps)}
function renderProperty(id){const p=property(id);if(!p.id)return missing();const vs=state.visits.filter(v=>v.propertyId===id);$('#main').innerHTML=`<a class="link back" href="#inmuebles">${icon('back')} Volver a inmuebles</a>`+heading(esc(p.code||'FICHA DEL INMUEBLE'),esc(p.title),esc(p.zone)+' · '+esc(p.operation),(canManageProperties()?button('Editar inmueble','edit-property','note','',`data-id="${esc(id)}"`)+(isAdmin()?button('Asignar asesores','assign-property','people','',`data-id="${esc(id)}"`):'')+(config.marketplace?button('Publicar en el portal','edit-publication','link','',`data-id="${esc(id)}"`):''):'')+button('Nueva visita','new-visit','mic','primary',`data-property="${esc(id)}"`))+`<div class="detail-grid"><div><section class="card"><div class="property-detail-art">${artwork(p)}</div><div class="card-header" style="margin-top:25px"><h2 style="font-size:25px">${money(p.price,p.currency)}${p.operation==='Alquiler'?'<small style="font-size:12px;color:#99a68c"> / mes</small>':''}</h2>${badge(p.status)}</div><p class="body-copy">${esc(p.description||'Sin descripción adicional.')}</p><div class="info-grid">${info('Superficie',`${p.area||0} m²`)}${info('Tipo',p.type)}${info('Dormitorios',p.bedrooms||0)}${info('Baños',p.bathrooms||0)}${info('Estacionamientos',p.parking||0)}${info('Dirección',p.address||'Sin registrar')}</div><div class="chips">${(p.features||[]).map(f=>`<span class="chip">${esc(f)}</span>`).join('')}</div></section><section class="card"><div class="card-header"><h2>Visitas de este inmueble</h2><span class="badge">${vs.length}</span></div>${vs.length?vs.map(visitRow).join(''):empty('Conocé la respuesta de cada visita','Las opiniones del cliente quedan vinculadas al inmueble.')}</section></div><div><section class="card"><div class="card-header"><h2>Propietario</h2></div>${p.ownerId&&client(p.ownerId).id?`<a class="person-row" href="#clientes/${esc(p.ownerId)}"><span class="avatar">${esc(initials(client(p.ownerId).name))}</span><div><h3>${esc(client(p.ownerId).name)}</h3><p>Ver ficha y contacto</p></div>${icon('arrow')}</a>`:empty('Propietario por registrar','Podés vincularlo desde Editar inmueble.')}</section><section class="card"><div class="card-header"><h2>Fotografías y documentos</h2>${canManageProperties()?button('Agregar','upload','upload','small',`data-id="${esc(id)}"`):''}</div>${fileList(id)}</section><section class="card"><h2>Clientes compatibles</h2><p class="subhead" style="margin:10px 0 16px">Encontrá qué clientes buscan un espacio como este.</p>${button('Encontrar interesados','reverse-matches','spark','soft',`data-id="${esc(id)}"`)}<div id="reverseMatches"></div></section></div></div>`}
function visitRow(v){return `<div class="visit-list-card"><div class="visit-date"><div>${new Date(v.date).getDate()}<small>${new Date(v.date).toLocaleDateString('es-BO',{month:'short'})}</small></div></div><div class="visit-list-body"><h3>${esc(client(v.clientId).name||'Cliente')} <span style="font-weight:400;color:#9aac8e">· ${esc(property(v.propertyId).zone||'Inmueble')}</span></h3><small class="responsible">${esc(v.advisor||advisorName(v.advisorId))}</small><p>${esc(v.sheet?.summary?.slice(0,110)||property(v.propertyId).title||'Hoja de visita en preparación')}</p></div><div class="actions">${badge(v.status)}<a class="link" href="#visitas/${esc(v.id)}">${v.status==='Confirmada'?'Ver hoja':'Continuar'} ${icon('arrow')}</a></div></div>`}
function renderVisits(){ $('#main').innerHTML=heading('CONVERSACIONES QUE ABREN PUERTAS','Visitas','Todo lo que se dijo, se acordó y queda por hacer.',button('Nueva visita','new-visit','mic','primary'))+demoNotice()+`<div class="filters"><div class="search">${icon('search')}<input id="visitSearch" placeholder="Buscar por cliente, inmueble o conversación…" aria-label="Buscar visitas"></div><select id="visitStatus" aria-label="Estado de visita"><option value="">Todas las visitas</option><option>Confirmada</option><option>Borrador</option></select></div><section class="card" id="visitList"></section>`;filterVisits()}
function filterVisits(){const t=($('#visitSearch')?.value||'').toLowerCase(),s=$('#visitStatus')?.value;const vs=state.visits.filter(v=>(!s||v.status===s)&&[client(v.clientId).name,property(v.propertyId).title,v.transcript,v.sheet?.summary].join(' ').toLowerCase().includes(t)).sort((a,b)=>b.date.localeCompare(a.date));$('#visitList').innerHTML=vs.length?vs.map(visitRow).join(''):empty('La próxima visita empieza acá','Grabá una conversación o pegá una transcripción para crear la hoja.','new-visit','Crear visita')}

function renderOperations(){const stages=['Contacto','Visita','Oferta','Negociación','Cierre'];$('#main').innerHTML=heading('DE LA PRIMERA CHARLA AL CIERRE','Operaciones','Cada oportunidad con su contexto, su etapa y su próximo paso.',button('Nueva operación','new-operation','plus','primary'))+demoNotice()+`<div class="kanban">${stages.map(s=>{const os=state.operations.filter(o=>o.stage===s);return `<section class="kanban-column" data-stage="${s}"><div class="kanban-title">${s}<span class="kanban-count">${os.length}</span></div>${os.map(o=>`<article class="deal-card" data-action="edit-operation" data-id="${esc(o.id)}"><div class="deal-top"><span class="avatar">${esc(initials(client(o.clientId).name))}</span><h3>${esc(client(o.clientId).name)}</h3></div><p>${esc(property(o.propertyId).title)}</p><div class="price">${money(o.value,o.currency)}</div><p>${esc(o.notes||'Agregá el próximo paso de esta oportunidad.')}</p><select data-operation="${esc(o.id)}" aria-label="Etapa de ${esc(client(o.clientId).name)}">${[...stages,'Descartada'].map(st=>`<option ${st===s?'selected':''}>${st}</option>`).join('')}</select></article>`).join('')||'<div class="list-placeholder">Próxima oportunidad</div>'}</section>`}).join('')}</div>${state.operations.some(o=>o.stage==='Descartada')?'<section class="card"><h2>Operaciones descartadas</h2>'+state.operations.filter(o=>o.stage==='Descartada').map(o=>`<div class="person-row"><div><h3>${esc(client(o.clientId).name)}</h3><p>${esc(property(o.propertyId).title)} · ${esc(o.notes||'')}</p></div>${button('Revisar','edit-operation','note','small',`data-id="${esc(o.id)}"`)}</div>`).join('')+'</section>':''}`}
function renderAgenda(){const es=state.events.slice().sort((a,b)=>a.date.localeCompare(b.date));$('#main').innerHTML=heading('UN BUEN SEGUIMIENTO HACE LA DIFERENCIA','Agenda','Visitas, contactos y compromisos en un mismo lugar.',button('Descargar calendario','export-calendar','download')+button('Agendar actividad','new-event','plus','primary'))+`<div class="filters"><div class="search">${icon('search')}<input id="eventSearch" placeholder="Buscar una actividad o cliente…" aria-label="Buscar actividad"></div><select id="eventStatus"><option>Pendiente</option><option value="">Todos los estados</option><option>Completada</option><option>Cancelada</option></select></div><section class="card" id="agendaList"></section>`;filterAgenda()}
function filterAgenda(){const t=($('#eventSearch')?.value||'').toLowerCase(),s=$('#eventStatus')?.value;const es=state.events.filter(e=>(!s||e.status===s)&&[e.title,client(e.clientId).name,e.notes].join(' ').toLowerCase().includes(t)).sort((a,b)=>a.date.localeCompare(b.date));let day='';$('#agendaList').innerHTML=es.length?es.map(e=>{const d=e.date.slice(0,10);const title=d!==day?`<div class="agenda-day">${longDate(e.date)}${d<today()&&e.status==='Pendiente'?' · Actividad atrasada':''}</div>`:'';day=d;return `${title}<div class="timeline-item"><div class="timeline-time">${time(e.date)}</div><span class="timeline-dot"></span><div class="timeline-body"><h3>${esc(e.title)}</h3><p>${esc(client(e.clientId).name||'Actividad del equipo')}${e.propertyId?' · '+esc(property(e.propertyId).zone):''}</p>${e.notes?'<p style="margin-top:5px">'+esc(e.notes)+'</p>':''}</div><div class="actions">${badge(e.status)}${e.status==='Pendiente'?button('Hecho','complete-event','check','small',`data-id="${esc(e.id)}"`):''}${button('Editar','edit-event','note','small',`data-id="${esc(e.id)}"`)}</div></div>`}).join(''):empty('Tu agenda está despejada','Agregá una visita o un seguimiento para organizar el próximo paso.','new-event','Agendar actividad')}

async function renderMatches(id){$('#main').innerHTML=heading('EL LUGAR INDICADO PARA LA PERSONA INDICADA','Coincidencias','Conectá las preferencias registradas con tu cartera disponible.')+`<section class="card"><div class="form-grid"><div class="field"><label for="matchClient">¿Para quién estamos buscando?</label><select id="matchClient"><option value="">Elegí un cliente</option>${clientOptions(id)}</select></div><div class="field" style="display:flex;align-items:flex-end">${button('Encontrar coincidencias','match-search','spark','primary')}</div></div><div class="notice">Cada resultado explica qué preferencias cumple y cuáles quedan pendientes.</div></section><div id="matches"></div>`;if(id)await showMatches(id)}
async function showMatches(id){if(!id)return toast('Elegí un cliente para buscar coincidencias.',true);$('#matches').innerHTML='<div class="loading">Conectando necesidades con espacios…</div>';const {matches}=await api('/api/matches/'+encodeURIComponent(id));$('#matches').innerHTML=matches.length?`<div class="match-grid">${matches.map(m=>`<article class="match-card"><div class="property-art">${artwork(m.property)}</div><div class="match-body"><div class="match-score">${m.score==null?'—':m.score+'%'} <small>${m.score==null?'Completá sus preferencias':'de criterios registrados'}</small></div><h3>${esc(m.property.title)}</h3><p class="subhead">${esc(m.property.zone)} · ${money(m.property.price,m.property.currency)}</p>${m.reasons.map(r=>`<div class="reason">${icon('check')}${esc(r)}</div>`).join('')}${m.missing.map(r=>`<div class="reason missing">${icon('close')}${esc(r)}</div>`).join('')}<div class="actions" style="margin-top:15px"><a class="btn small" href="#inmuebles/${esc(m.property.id)}">Ver ficha</a>${button('Agendar visita','new-event','calendar','small primary',`data-client="${esc(id)}" data-property="${esc(m.property.id)}"`)}</div></div></article>`).join('')}</div>`:empty('Necesitamos inmuebles disponibles','Agregá propiedades a tu cartera para encontrar coincidencias.','new-property','Agregar inmueble')}
function renderReports(){const active=state.operations.filter(o=>!['Cierre','Descartada'].includes(o.stage)),closed=state.operations.filter(o=>o.stage==='Cierre');const months=Array.from({length:6},(_,i)=>{let d=new Date();d.setMonth(d.getMonth()-5+i);return {key:localISO(d).slice(0,7),label:d.toLocaleDateString('es-BO',{month:'short'})}});const counts=months.map(m=>state.visits.filter(v=>v.date.startsWith(m.key)).length),max=Math.max(1,...counts);const monetary=closed.reduce((a,o)=>{a[o.currency||'USD']=(a[o.currency||'USD']||0)+Number(o.value||0);return a},{});$('#main').innerHTML=heading('DATOS QUE AYUDAN A DECIDIR','Reportes','Una vista clara de la actividad y las oportunidades del equipo.',button('Exportar datos','export-data','download'))+`<div class="stats">${stat('Visitas registradas',state.visits.length,'mic','Historial completo')}${stat('Hojas confirmadas',state.visits.filter(v=>v.status==='Confirmada').length,'file','Revisadas por el asesor')}${stat('Operaciones activas',active.length,'deal','En seguimiento comercial')}${stat('Cierres registrados',closed.length,'check',`${state.operations.length?Math.round(closed.length/state.operations.length*100):0}% de las operaciones`)}</div><div class="detail-grid"><section class="card"><div class="card-header"><h2>Visitas en los últimos seis meses</h2></div><div class="report-bars">${months.map((m,i)=>`<div class="bar-group"><small>${counts[i]}</small><div class="bar" style="height:${counts[i]/max*110}px"></div><span>${m.label}</span></div>`).join('')}</div></section><section class="card"><h2>Valor de operaciones cerradas</h2>${Object.entries(monetary).map(([c,n])=>`<div class="report-money">${money(n,c)}</div>`).join('')||'<div class="report-money">—</div>'}<p class="subhead">Valor de los inmuebles de operaciones cerradas, separado por moneda. No representa comisiones ni ingresos cobrados.</p></section></div><section class="card"><div class="card-header"><h2>De cada conversación, un aprendizaje</h2></div><div class="info-grid">${info('Seguimientos pendientes',state.events.filter(e=>e.status==='Pendiente').length)}${info('Visitas sin confirmar',state.visits.filter(v=>v.status==='Borrador').length)}${info('Compradores',state.clients.filter(c=>c.role==='Comprador').length)}${info('Propietarios',state.clients.filter(c=>c.role==='Propietario').length)}</div></section>`}
function renderSettings(){if(!isAdmin())return renderProfile();if(config.marketplace&&!config.profile?.platformAdmin)return renderWorkspaceSettings();const connections=[['spark','Notas y memoria con IA',config.ai,'Organiza conversaciones y responde sobre el historial con OpenAI.','OPENAI_API_KEY'],['mic','Transcripción de grabaciones',config.transcription,'Procesa audios con '+(config.transcriptionProvider==='openai'?'OpenAI':'AssemblyAI')+'. La separación de hablantes depende del modelo seleccionado.','OPENAI_API_KEY o ASSEMBLYAI_API_KEY'],['phone','WhatsApp',config.whatsapp,'Envía mensajes revisados desde la ficha del cliente. También podés abrir WhatsApp y enviarlos personalmente.','WHATSAPP_TOKEN · WHATSAPP_PHONE_NUMBER_ID'],['calendar','Google Calendar',config.calendar,'Envía las actividades al calendario conectado. La descarga de calendario funciona sin conexión externa.','GOOGLE_CALENDAR_TOKEN · GOOGLE_CALENDAR_ID'],['phone','Recepción por voz',config.voice,'Prepara una conexión a Vapi para consultar disponibilidad y coordinar visitas. Requiere configurar el asistente y sus herramientas.','VAPI_SERVER_SECRET']];$('#main').innerHTML=heading('UN ESPACIO A TU MEDIDA','Configuración','Tus conexiones, tus datos y tu manera de trabajar.')+`<section class="card"><div class="card-header"><h2>Tu espacio de trabajo</h2>${badge('Datos en servidor')}</div><div class="info-grid">${info('Equipo',config.user||'Equipo Nexo')}${info('Aplicación','Nexo Inmobiliaria · 2.1')}</div><div class="actions">${button('Exportar respaldo de datos','export-data','download')}${button('Conectar audio e IA','connect-transcription','mic')}${config.ai?button('Verificar OpenAI','verify-openai','check'):''}${button('Activar avisos en este dispositivo','notifications','bell')}</div><p class="notice">Los avisos del dispositivo se comprueban mientras Nexo está abierto. Conservá un respaldo de la base de datos y de los archivos del servidor.</p></section><div class="connection-grid">${connections.map(([i,title,on,desc,key])=>`<section class="connection-card"><div class="connection-head"><span class="connection-symbol">${icon(i)}</span><h3>${title}</h3>${badge(on?'Configurado':'Por conectar')}</div><p>${desc}</p><details><summary class="link">Cómo conectar</summary><p>Configurá estas variables en el servidor y reiniciá la aplicación:</p><code>${key}</code></details></section>`).join('')}</div><div class="callout">Antes de grabar una visita, obtené la autorización de las personas presentes. Las hojas se revisan y confirman; los datos ausentes quedan sin completar.</div>`}
function missing(){ $('#main').innerHTML=empty('No encontramos esta ficha','Puede que el registro ya no exista. Volvé a la lista desde el menú.') }

function openModal(title,body){if(modal)closeModal();modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${body}</div></section>`;$('#modalRoot').append(modal);document.body.classList.add('modal-open');modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});setTimeout(()=>$('input,select,textarea,button',modal)?.focus(),20)}
function closeModal(){modal?.remove();modal=null;document.body.classList.remove('modal-open')}
function inputField(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function selectField(label,name,options,value='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [val,text]=Array.isArray(o)?o:[o,o];return `<option value="${esc(val)}" ${val===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></div>`}
function textField(label,name,value='',placeholder=''){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`}
function formFooter(label='Guardar'){return `<div class="form-error" id="formError" role="alert"></div><div class="form-footer">${button('Cancelar','close-modal')}<button class="btn primary" type="submit">${icon('check')}${label}</button></div>`}
function clientOptions(selected){return state.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(c.role)}</option>`).join('')}
function propertyOptions(selected){return state.properties.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.code||'')} · ${esc(p.title)}</option>`).join('')}
function clientForm(id){const c=id?client(id):{role:'Comprador',intent:'Venta',currency:'USD',needs:[],zones:[]};openModal(id?'Editar cliente':'Una nueva conexión',`<form id="clientForm" data-id="${esc(id||'')}"><div class="form-grid">${inputField('Nombre completo *','name',c.name,'text','required maxlength="120"')}${selectField('Tipo de cliente','role',['Comprador','Propietario','Inquilino','Inversor'],c.role)}${inputField('Teléfono con código de país','phone',c.phone,'tel','placeholder="591…"')}${inputField('Correo electrónico','email',c.email,'email')}${selectField('Busca','intent',['Venta','Alquiler'],c.intent)}${selectField('Tipo de inmueble','propertyType',[['','Por definir'],'Departamento','Casa','Terreno','Oficina','Local comercial'],c.propertyType)}${inputField('Presupuesto máximo','budget',c.budget||'','number','min="0" step="any"')}${selectField('Moneda','currency',['USD','BOB'],c.currency)}${inputField('Dormitorios mínimos','bedrooms',c.bedrooms||'','number','min="0" max="30"')}${inputField('Zonas de interés, separadas por coma','zones',(c.zones||[]).join(', '))}${textField('Necesidades y preferencias','needs',listText(c.needs),'Una necesidad por línea')}${isAdmin()&&!id?advisorField(null):''}${textField('Notas del asesor','notes',c.notes)}</div>${formFooter()}</form>`)}
function propertyForm(id){if(!canManageProperties())return toast('Los inmuebles se administran desde el panel central.',true);const p=id?property(id):{type:'Departamento',operation:'Venta',status:'Disponible',currency:'USD',features:[]};openModal(id?'Editar inmueble':'Un nuevo espacio en tu cartera',`<form id="propertyForm" data-id="${esc(id||'')}"><div class="form-grid">${inputField('Título *','title',p.title,'text','required maxlength="180"')}${inputField('Código de referencia','code',p.code||'INM-'+String(state.properties.length+1).padStart(3,'0'))}${selectField('Tipo','type',['Departamento','Casa','Terreno','Oficina','Local comercial'],p.type)}${selectField('Operación','operation',['Venta','Alquiler'],p.operation)}${inputField('Precio *','price',p.price,'number','required min="0" step="any"')}${selectField('Moneda','currency',['USD','BOB'],p.currency)}${inputField('Zona / barrio *','zone',p.zone,'text','required')}${inputField('Dirección','address',p.address)}${inputField('Superficie en m²','area',p.area,'number','min="0" step="any"')}${inputField('Dormitorios','bedrooms',p.bedrooms,'number','min="0" max="30"')}${inputField('Baños','bathrooms',p.bathrooms,'number','min="0" max="30"')}${inputField('Estacionamientos','parking',p.parking,'number','min="0" max="30"')}${selectField('Estado','status',['Disponible','Reservado','Vendido','Alquilado','Pausado'],p.status)}${selectField('Propietario','ownerId',[['','Sin vincular'],...state.clients.filter(c=>c.role==='Propietario').map(c=>[c.id,c.name])],p.ownerId)}${isAdmin()&&!id?propertyAdvisorFields([]):''}${textField('Descripción','description',p.description)}${textField('Características destacadas','features',listText(p.features),'Balcón\nAscensor\nJardín')}</div>${formFooter()}</form>`)}
function eventForm(id,defaults={}){const e=id?state.events.find(e=>e.id===id):{type:'Visita',status:'Pendiente',date:localISO(),...defaults};openModal(id?'Editar actividad':'Organizá el próximo paso',`<form id="eventForm" data-id="${esc(id||'')}"><div class="form-grid">${inputField('Actividad *','title',e.title,'text','required')}${inputField('Fecha y hora *','date',e.date,'datetime-local','required')}${selectField('Tipo','type',['Visita','Seguimiento','Llamada','Documentación','Otro'],e.type)}${selectField('Estado','status',['Pendiente','Completada','Cancelada'],e.status)}${selectField('Cliente','clientId',[['','Actividad del equipo'],...state.clients.map(c=>[c.id,c.name])],e.clientId)}${selectField('Inmueble','propertyId',[['','Sin vincular'],...state.properties.map(p=>[p.id,p.title])],e.propertyId)}${isAdmin()?advisorField(e.advisorId):''}${textField('Notas y acuerdos','notes',e.notes)}</div>${formFooter()}</form>`)}
function operationForm(id,defaults={}){if(!state.clients.length||!state.properties.length)return toast('Agregá un cliente y un inmueble antes de crear la operación.',true);const o=id?state.operations.find(o=>o.id===id):{stage:'Contacto',currency:'USD',...defaults};openModal(id?'Revisar operación':'Una nueva oportunidad',`<form id="operationForm" data-id="${esc(id||'')}"><div class="form-grid">${selectField('Cliente *','clientId',state.clients.map(c=>[c.id,c.name]),o.clientId)}${selectField('Inmueble *','propertyId',state.properties.map(p=>[p.id,p.title]),o.propertyId)}${selectField('Etapa','stage',['Contacto','Visita','Oferta','Negociación','Cierre','Descartada'],o.stage)}${selectField('Moneda','currency',['USD','BOB'],o.currency)}${inputField('Valor de la operación','value',o.value||'','number','min="0" step="any"')}${isAdmin()?advisorField(o.advisorId):''}${textField('Contexto y próximo paso','notes',o.notes)}</div>${formFooter()}</form>`)}

function newVisit(defaults={}){if(!state.clients.length||!state.properties.length){openModal('Prepará tu primera visita',`<p class="body-copy">La hoja de visita se vincula a una persona y a un inmueble. ${isAdmin()?'Registralos primero para conservar todo el contexto.':'Registrá tu cliente y pedile al administrador que te asigne un inmueble.'}</p><div class="actions">${button('Nuevo cliente','new-client','people','primary')}${isAdmin()?button('Agregar inmueble','new-property','building'):''}</div>`);return}visitDraft={date:localISO(),advisor:config.user||'Equipo Nexo',clientId:defaults.clientId||state.clients[0].id,propertyId:defaults.propertyId||state.properties[0].id,transcript:'',status:'Borrador',sheet:null};location.hash='#visitas/nueva';if(route==='visitas')renderVisit('nueva')}
function renderVisit(id){if(id!=='nueva'){const v=state.visits.find(v=>v.id===id);if(!v)return missing();visitDraft=structuredClone(v)}else if(!visitDraft){visitDraft={date:localISO(),advisor:config.user,clientId:state.clients[0]?.id,propertyId:state.properties[0]?.id,transcript:'',status:'Borrador'}}const v=visitDraft;if(v.status==='Confirmada')return renderConfirmedVisit(v);$('#main').innerHTML=`<a class="link back" href="#visitas">${icon('back')} Volver a visitas</a>`+heading('VOS ACOMPAÑÁS. NEXO ORGANIZA.','Una visita, todo su contexto','Capturá la conversación y revisá la hoja antes de incorporarla al historial.',button('Guardar borrador','save-draft','file'))+`<div class="visit-steps"><div class="visit-step active"><span>1</span>Preparar visita</div>${icon('arrow')}<div class="visit-step"><span>2</span>Capturar conversación</div>${icon('arrow')}<div class="visit-step"><span>3</span>Revisar y confirmar</div></div><div class="visit-layout"><section class="card"><div class="card-header"><h2>La conversación</h2>${badge('Borrador')}</div><div class="form-grid"><div class="field"><label for="visitClient">Cliente</label><select id="visitClient">${clientOptions(v.clientId)}</select></div><div class="field"><label for="visitProperty">Inmueble</label><select id="visitProperty">${propertyOptions(v.propertyId)}</select></div><div class="field"><label for="visitDate">Fecha y hora</label><input id="visitDate" type="datetime-local" value="${esc(v.date)}"></div><div class="field"><label for="visitAdvisor">Asesor</label><input id="visitAdvisor" value="${esc(v.advisor||config.user)}" ${isAdmin()?'':'readonly'}></div></div><div class="recorder"><div class="record-circle" id="recordCircle">${icon('mic')}</div><div class="wave" id="recordWave">${'<span></span>'.repeat(13)}</div><div class="record-timer mono" id="recordTimer">00:00</div><p class="record-status" id="recordStatus">Una conversación natural. Un registro completo.</p><div class="consent-box"><label class="check-row"><input type="checkbox" id="recordConsent">Las personas presentes autorizaron la grabación de esta visita.</label></div><div class="actions" style="margin-top:16px">${button('Comenzar grabación','record','mic','primary','id="recordButton"')}${button('Subir audio','upload-audio','upload')}</div><div id="audioPreview"></div><p class="recording-mobile-note">Durante la grabación, mantené Nexo visible y la pantalla desbloqueada.</p><p class="notice">El audio se conserva en la visita. Si el navegador permite transcripción en vivo, su texto aparece abajo.</p></div><div class="section-label"><label for="visitTranscript">Transcripción o notas de la visita</label><button class="link" data-action="visit-example">Probar un ejemplo</button></div><textarea id="visitTranscript" style="min-height:170px" placeholder="El texto de la conversación aparecerá acá. También podés pegar una transcripción o dictar tus notas después de la visita.">${esc(v.transcript)}</textarea><div class="actions" style="justify-content:space-between;margin-top:16px">${button('Transcribir y generar hoja','transcribe-file','mic')}${button('Generar hoja de visita','generate-sheet','spark','primary','id="generateButton"')}</div><div class="actions" style="margin-top:10px">${button('Organizar texto sin IA','generate-local-sheet','note','small')}</div><div id="transcriptionStatus" class="callout">${config.transcription?'Transcripción de audio conectada. Al detener la grabación se preparará la hoja.':'La grabación se guarda. Para preparar la hoja desde el audio, conectá la transcripción.'}</div>${!config.transcription?button('Conectar transcripción','connect-transcription','link','soft'):''}<div class="callout">Se completa únicamente lo mencionado. Revisá cifras, acuerdos y fechas antes de confirmar.</div>${v.id&&filesFor(v.id).length?'<div class="section-label">Archivos de esta visita</div>'+fileList(v.id):''}</section><section class="card" id="visitSheet"></section></div>`;paintSheet(v.sheet)}
const sheetLabels={summary:'Resumen de la visita',needs:'Necesidades y requisitos',zones:'Zonas mencionadas',likes:'Qué le gustó',objections:'Objeciones y aspectos por resolver',questions:'Preguntas pendientes',agreements:'Acuerdos',nextStep:'Próximo paso'};
function paintSheet(sheet){const root=$('#visitSheet');if(!root)return;if(!sheet){root.innerHTML=`<div class="sheet-placeholder">${icon('file')}<h3>Tu hoja de visita se prepara acá.</h3><p>Agregá la conversación y Nexo organizará los puntos que importan.</p><span class="badge">Esperando la conversación</span></div>`;return}const v=visitDraft;root.innerHTML=`<div class="sheet-brand"><strong>nexo.</strong><small>HOJA DE VISITA · BORRADOR</small></div><div class="sheet-title">Una visita, un próximo paso.</div><div class="sheet-meta">${esc(client(v.clientId).name)} · ${esc(property(v.propertyId).title)}<br>${shortDate(v.date)} · ${time(v.date)} · ${esc(v.advisor)}</div>${Object.entries(sheetLabels).map(([key,label])=>`<div class="sheet-section"><label for="sheet-${key}">${label}</label><textarea id="sheet-${key}" data-sheet="${key}" placeholder="No mencionado">${esc(Array.isArray(sheet[key])?listText(sheet[key]):sheet[key]||'')}</textarea></div>`).join('')}<div class="sheet-section"><div class="form-grid">${inputField('Presupuesto mencionado','sheetBudget',sheet.budget??'','number','min="0" step="any"')}${selectField('Moneda','sheetCurrency',[['','No mencionada'],'USD','BOB'],sheet.currency||'')}${inputField('Oferta mencionada','sheetOffer',sheet.offer??'','number','min="0" step="any"')}${selectField('Interés expresado','sheetInterest',[['','No mencionado'],'Alto','Medio','Bajo'],sheet.interest||'')}${inputField('Fecha de seguimiento','sheetFollowUp',sheet.followUp||'','date')}</div></div><div class="sheet-section no-print"><label class="check-row"><input type="checkbox" id="applyPreferences" checked>Actualizar preferencias y presupuesto del cliente con lo revisado.</label><label class="check-row"><input type="checkbox" id="applyFollowUp" ${sheet.nextStep&&sheet.followUp?'checked':''}>Crear seguimiento en la agenda con este próximo paso.</label>${button('Confirmar y guardar hoja','confirm-visit','check','primary','style="width:100%;margin-top:12px" id="confirmButton"')}<p class="audit-note">Al confirmar, la hoja queda registrada y pasa a ser de solo lectura.</p></div>`}
function readVisit(){if($('#visitClient'))Object.assign(visitDraft,{clientId:$('#visitClient').value,propertyId:$('#visitProperty').value,date:$('#visitDate').value,advisor:$('#visitAdvisor').value,transcript:$('#visitTranscript').value});return visitDraft}
function readSheet(){const s=structuredClone(visitDraft.sheet||{});$$('[data-sheet]').forEach(t=>s[t.dataset.sheet]=['needs','zones','likes','objections','questions','agreements'].includes(t.dataset.sheet)?lines(t.value):t.value.trim()||null);if($('#f-sheetBudget'))Object.assign(s,{budget:$('#f-sheetBudget').value?Number($('#f-sheetBudget').value):null,currency:$('#f-sheetCurrency').value||null,offer:$('#f-sheetOffer').value?Number($('#f-sheetOffer').value):null,interest:$('#f-sheetInterest').value||null,followUp:$('#f-sheetFollowUp').value||null});return s}
async function persistVisit(readEditedSheet=true,target=visitDraft,readForm=true){if(readForm&&target===visitDraft)readVisit();const body={...target,sheet:target.sheet?(readEditedSheet&&target===visitDraft?readSheet():target.sheet):null};const r=await api('/api/visits'+(target.id?'/'+encodeURIComponent(target.id):''),{method:target.id?'PATCH':'POST',body:JSON.stringify(body)});Object.assign(target,r);await refresh();renderNav();return r}
async function generateSheet(local=false){
 if(recordStarting||recorder?.state==='recording'||uploading)return toast('Detené la grabación y esperá a que se guarde el audio.',true);
 if(transcriptionRuns.has(visitDraft?.id))return toast('Esperá a que termine la transcripción.',true);
 readVisit();let transcript=String(visitDraft.transcript||'').trim();
 if(transcript.length<15){
  if(local)return toast('Agregá el texto de la conversación o tus notas para organizar la hoja.',true);
  if(!audioForVisit(visitDraft))return toast('Grabá una visita, subí un audio o agregá el texto de la conversación.',true);
  if(!config.transcription){setTranscriptionStatus('El audio está guardado, pero falta conectar su transcripción.',true);transcriptionSetup();return}
  const result=await transcribeSavedVisit();if(!result||visitDraft?.id!==result.visitId||!$('#visitTranscript'))return;transcript=result.text;
 }
 const target=visitDraft;const b=$('#generateButton');if(b){b.disabled=true;b.innerHTML=icon('spark')+'Preparando la hoja…'}
 try{const result=await api('/api/analyse',{method:'POST',body:JSON.stringify({text:transcript,local})});target.transcript=transcript;target.sheet=result.sheet;target.method=result.method;await persistVisit(false,target,false);if(visitDraft?.id===target.id&&$('#visitSheet')){paintSheet(result.sheet);setTranscriptionStatus(result.method==='ai'?'Hoja preparada con IA. Revisá sus datos y confirmá el guardado.':'Hoja organizada desde el texto disponible. Revisá sus datos antes de confirmar.');$('#visitSheet')?.scrollIntoView({behavior:'smooth',block:'start'})}toast('Hoja preparada y guardada como borrador. Revisá y confirmá los datos.')}
 finally{if(b?.isConnected){b.disabled=false;b.innerHTML=icon('spark')+'Generar hoja de visita'}}
}
async function confirmVisit(){if(recordStarting||recorder?.state==='recording'||uploading||transcriptionRuns.has(visitDraft?.id))return toast('Esperá a que termine la grabación y el procesamiento antes de confirmar.',true);readVisit();const sheet=readSheet();if(!visitDraft.id)await persistVisit();const b=$('#confirmButton');b.disabled=true;try{const r=await api('/api/visits/'+encodeURIComponent(visitDraft.id)+'/confirm',{method:'POST',body:JSON.stringify({sheet,updateClient:$('#applyPreferences').checked,createFollowUp:$('#applyFollowUp').checked})});visitDraft=r;await refresh();location.hash='#visitas/'+r.id;renderConfirmedVisit(r);renderNav();toast('Hoja confirmada y guardada en el historial.')}finally{if(b.isConnected)b.disabled=false}}
function renderConfirmedVisit(v){$('#main').innerHTML=`<a class="link back" href="#visitas">${icon('back')} Volver a visitas</a>`+heading('UNA CONVERSACIÓN QUE QUEDA','Hoja de visita',esc(client(v.clientId).name)+' · '+esc(property(v.propertyId).zone),button('Imprimir / PDF','print','print')+button('Preparar seguimiento','new-event','calendar','primary',`data-client="${esc(v.clientId)}" data-property="${esc(v.propertyId)}"`))+`<div class="visit-layout"><section class="card no-print"><div class="card-header"><h2>Conversación original</h2>${badge('Confirmada')}</div><p class="body-copy">${esc(v.transcript||'No hay transcripción registrada.')}</p><div class="section-label">Grabación y archivos</div>${fileList(v.id)}<div class="suggested-actions"><a class="btn soft" href="#clientes/${esc(v.clientId)}">${icon('people')}Ver cliente</a><a class="btn" href="#inmuebles/${esc(v.propertyId)}">${icon('building')}Ver inmueble</a></div></section><section class="card sheet-readonly"><div class="sheet-brand"><strong>nexo.</strong><small>HOJA DE VISITA · ${esc(v.id.slice(0,8).toUpperCase())}</small></div><div class="sheet-title">Registro de visita inmobiliaria</div><div class="sheet-meta"><strong>Cliente:</strong> ${esc(client(v.clientId).name)}<br><strong>Inmueble:</strong> ${esc(property(v.propertyId).title)}<br><strong>Fecha:</strong> ${shortDate(v.date)} · ${time(v.date)}<br><strong>Asesor:</strong> ${esc(v.advisor)}</div>${Object.entries(sheetLabels).map(([k,l])=>`<div class="sheet-section"><label>${l}</label><p>${esc(Array.isArray(v.sheet?.[k])?listText(v.sheet[k]):v.sheet?.[k]||'')}</p></div>`).join('')}<div class="sheet-section"><div class="info-grid">${info('Presupuesto',v.sheet?.budget?(v.sheet.currency?money(v.sheet.budget,v.sheet.currency):Number(v.sheet.budget).toLocaleString('es-BO')+' · moneda no mencionada'):'No mencionado')}${info('Interés expresado',v.sheet?.interest||'No mencionado')}${info('Oferta',v.sheet?.offer?(v.sheet.currency?money(v.sheet.offer,v.sheet.currency):Number(v.sheet.offer).toLocaleString('es-BO')+' · moneda no mencionada'):'No mencionada')}${info('Seguimiento',v.sheet?.followUp?shortDate(v.sheet.followUp):'Sin fecha acordada')}</div></div><p class="audit-note">Revisada y confirmada el ${shortDate(v.confirmedAt)} a las ${time(v.confirmedAt)}. Los campos vacíos no fueron mencionados o quedaron pendientes de completar.</p></section></div>`}

async function startRecording(){
 if(recorder?.state==='recording'){stopRecording();return}
 if(recordStarting||uploading||transcriptionRuns.has(visitDraft?.id))return toast('Esperá a que termine el procesamiento de la grabación.',true);
 recordStarting=true;const button=$('#recordButton');if(button)button.disabled=true;
 try{await beginRecording()}catch(error){recStream?.getTracks().forEach(t=>t.stop());recognition?.stop();recognition=null;clearInterval(recTimer);const message=error.name==='NotAllowedError'?'Habilitá el permiso de micrófono de Chrome para grabar.':error.name==='NotFoundError'?'No se encontró un micrófono disponible.':error.message;throw Error(message)}
 finally{recordStarting=false;if(button?.isConnected)button.disabled=false}
}
async function beginRecording(){if(recorder?.state==='recording'){stopRecording();return}if(!$('#recordConsent').checked)return toast('Confirmá la autorización de las personas presentes para grabar.',true);if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Este navegador no permite grabar acá. Usá un navegador compatible en HTTPS o subí un audio.',true);readVisit();visitDraft.recordingConsentAt=new Date().toISOString();await persistVisit();recStream=await navigator.mediaDevices.getUserMedia({audio:true});const types=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];const type=types.find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(recStream,type?{mimeType:type,audioBitsPerSecond:64000}:{audioBitsPerSecond:64000});const recordedVisit=visitDraft,ownerId=config.profile.id;const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{const durationSeconds=Math.max(1,Math.ceil((Date.now()-recStart)/1000));uploading=true;try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const extension=blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm';const f=await storeAndUploadAudio(blob,recordedVisit.id,'Visita-'+today()+'.'+extension,ownerId);recordedVisit.audioId=f.id;recordedVisit.transcriptionJobId=null;recordedVisit.audioDurationSeconds=durationSeconds;await api('/api/visits/'+encodeURIComponent(recordedVisit.id),{method:'PATCH',body:JSON.stringify({audioId:f.id,transcriptionJobId:null,audioDurationSeconds:durationSeconds})});await refresh();if(visitDraft?.id===recordedVisit.id){visitDraft.audioId=f.id;visitDraft.transcriptionJobId=null;visitDraft.audioDurationSeconds=durationSeconds;readVisit();await persistVisit()}const root=visitDraft?.id===recordedVisit.id?$('#audioPreview'):null;if(root)root.innerHTML=`<audio class="audio-player" controls src="/api/files/${encodeURIComponent(f.id)}"></audio><div class="notice">Grabación guardada en esta visita.</div>`;toast('Grabación guardada.')}catch(e){toast(e.message,true)}finally{uploading=false}if(visitDraft?.id===recordedVisit.id)await afterAudioSaved()};recorder.start();recStart=Date.now();$('#recordCircle').classList.add('live');$('#recordWave').classList.add('live');$('#recordButton').innerHTML=icon('stop')+'Detener y guardar';$('#generateButton').disabled=true;$('#recordStatus').textContent='Grabando la visita. El audio se guardará al detener.';recTimer=setInterval(()=>{const sec=Math.floor((Date.now()-recStart)/1000);if($('#recordTimer'))$('#recordTimer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')},500);const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(Speech){recognition=new Speech();recognition.lang='es-BO';recognition.continuous=true;recognition.interimResults=false;recognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal&&$('#visitTranscript'))$('#visitTranscript').value+=($('#visitTranscript').value?' ':'')+e.results[i][0].transcript}};recognition.onerror=()=>{if($('#recordStatus'))$('#recordStatus').textContent='El audio sigue grabándose. La transcripción en vivo no está disponible; transcribí el archivo o agregá notas al terminar.'};try{recognition.start()}catch{}}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();recognition?.stop();recognition=null;recStream?.getTracks().forEach(t=>t.stop());clearInterval(recTimer);$('#recordCircle')?.classList.remove('live');$('#recordWave')?.classList.remove('live');if($('#recordButton'))$('#recordButton').innerHTML=icon('mic')+'Grabar nuevamente';if($('#recordStatus'))$('#recordStatus').textContent='Guardando la grabación…';if($('#generateButton'))$('#generateButton').disabled=false}
async function uploadFile(recordId,audio=false){
 const target=audio?visitDraft:null;const input=document.createElement('input');input.type='file';input.accept=audio?'audio/*':'image/jpeg,image/png,image/webp,image/gif,application/pdf,text/plain,audio/*';
 input.onchange=async()=>{const file=input.files[0];if(!file)return;if(audio)uploading=true;
 try{if(file.size>80*1024*1024)throw Error('El archivo supera 80 MB.');if(audio&&config.transcriptionProvider==='openai'&&file.size>25*1024*1024)throw Error('OpenAI admite hasta 25 MB por audio. Dividí la grabación en archivos más cortos.');
 const f=await api('/api/files?recordId='+encodeURIComponent(recordId)+'&name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});
 if(audio&&target){Object.assign(target,{audioId:f.id,transcriptionJobId:null});await api('/api/visits/'+encodeURIComponent(recordId),{method:'PATCH',body:JSON.stringify({audioId:f.id,transcriptionJobId:null})});await refresh();if(visitDraft?.id===recordId){Object.assign(visitDraft,{audioId:f.id,transcriptionJobId:null});if($('#audioPreview'))$('#audioPreview').innerHTML=`<audio class="audio-player" controls src="/api/files/${encodeURIComponent(f.id)}"></audio><div class="notice">Audio guardado.</div>`}}
 else{if(file.type.startsWith('image/')&&property(recordId).id)await api('/api/properties/'+encodeURIComponent(recordId),{method:'PATCH',body:JSON.stringify({photoId:f.id})});await refresh();startPage()}
 toast('Archivo guardado en su ficha.');
 }catch(error){toast(error.message,true)}finally{if(audio)uploading=false}
 if(audio&&visitDraft?.id===recordId&&document.getElementById('visitTranscript'))await afterAudioSaved()
 };input.click()
}
async function transcribeFile(){const result=await transcribeSavedVisit();if(result&&visitDraft?.id===result.visitId&&$('#visitTranscript'))await generateSheet()}

async function whatsappModal(id){const c=client(id);openModal('Prepará el próximo contacto',`<p class="subhead">Para ${esc(c.name)}${c.phone?' · '+esc(c.phone):''}</p><label for="whatsappMessage" style="margin-top:18px">Mensaje que querés enviar</label><textarea id="whatsappMessage" style="min-height:135px">${esc('Hola '+c.name.split(' ')[0]+', gracias por tu visita. ¿Coordinamos el próximo paso?')}</textarea><div class="callout">Revisá el mensaje antes de enviarlo. Se comparte únicamente el texto que aparece arriba.</div><div class="actions">${button('Abrir en WhatsApp','wa-open','phone','primary',`data-id="${esc(id)}"`)}${config.whatsapp?button('Enviar con la cuenta conectada','wa-send','arrow','',`data-id="${esc(id)}"`):''}</div>`)}
function download(name,text,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function calendarText(){const protect=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Nexo//Agenda inmobiliaria//ES','CALSCALE:GREGORIAN',...state.events.filter(e=>e.status==='Pendiente').flatMap(e=>{const start=new Date(e.date),end=new Date(start.getTime()+45*60000);const fmt=d=>d.toISOString().replace(/[-:]/g,'').slice(0,15)+'Z';return ['BEGIN:VEVENT','UID:'+e.id+'@nexo','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:'+protect(e.title),'DESCRIPTION:'+protect(e.notes),'END:VEVENT']}),'END:VCALENDAR'].join('\r\n')}

document.addEventListener('submit',async e=>{if(!e.target.matches('#clientForm,#propertyForm,#operationForm,#eventForm'))return;e.preventDefault();const form=e.target,b=$('[type="submit"]',form);b.disabled=true;try{const data=Object.fromEntries(new FormData(form));let kind=({clientForm:'clients',propertyForm:'properties',operationForm:'operations',eventForm:'events'})[form.id];const id=form.dataset.id;for(const k of ['budget','price','area','bedrooms','bathrooms','parking','value'])if(k in data)data[k]=data[k]?Number(data[k]):0;if(isAdmin()&&kind==='properties'&&!id)data.advisorIds=new FormData(form).getAll('advisorIds');if('advisorId' in data&&!data.advisorId)data.advisorId=null;if('zones' in data)data.zones=data.zones.split(',').map(x=>x.trim()).filter(Boolean);for(const k of ['needs','features'])if(k in data)data[k]=lines(data[k]);for(const k of ['ownerId','clientId','propertyId'])if(k in data&&!data[k])data[k]=null;if(kind==='operations'&&!data.value){const p=property(data.propertyId);data.value=p.price;data.currency=p.currency}await api('/api/'+kind+(id?'/'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',body:JSON.stringify(data)});closeModal();await refresh();startPage();toast('Ficha guardada.')}catch(e){$('#formError',form).textContent=e.message}finally{b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.matches('#clientSearch'))filterClients();if(e.target.matches('#propertySearch'))filterProperties();if(e.target.matches('#visitSearch'))filterVisits();if(e.target.matches('#eventSearch'))filterAgenda()});
document.addEventListener('change',async e=>{if(e.target.id==='clientRole')filterClients();if(e.target.matches('#propertyOperation,#propertyStatus'))filterProperties();if(e.target.id==='visitStatus')filterVisits();if(e.target.id==='eventStatus')filterAgenda();if(e.target.id==='matchClient'&&e.target.value){try{await showMatches(e.target.value)}catch(err){toast(err.message,true)}}if(e.target.dataset.operation){try{await api('/api/operations/'+encodeURIComponent(e.target.dataset.operation),{method:'PATCH',body:JSON.stringify({stage:e.target.value})});await refresh();renderOperations();toast('Etapa actualizada.')}catch(err){toast(err.message,true)}}});
document.addEventListener('click',async e=>{if(e.target.tagName==='SELECT'||e.target.closest('select'))return;const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
if(a==='new-client')clientForm();if(a==='edit-client')clientForm(id);if(a==='new-property')propertyForm();if(a==='edit-property')propertyForm(id);if(a==='property-detail')location.hash='#inmuebles/'+id;if(a==='close-modal')closeModal();if(a==='new-event')eventForm(null,{clientId:el.dataset.client,propertyId:el.dataset.property});if(a==='edit-event')eventForm(id);if(a==='new-operation')operationForm(null,{clientId:el.dataset.client});if(a==='edit-operation')operationForm(id);if(a==='new-visit')newVisit({clientId:el.dataset.client,propertyId:el.dataset.property});if(a==='goto-matches')location.hash='#coincidencias/'+id;if(a==='match-search')await showMatches($('#matchClient').value);
if(a==='demo'){el.disabled=true;await api('/api/demo',{method:'POST'});await refresh();startPage();toast('Demo cargada. Estos registros son ficticios.')}
if(a==='complete-event'){await api('/api/events/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:'Completada'})});await refresh();renderAgenda();toast('Actividad completada.')}
if(a==='ask'){const q=$('#historyQuestion').value;el.disabled=true;const r=await api('/api/ask',{method:'POST',body:JSON.stringify({clientId:id,question:q})});$('#historyAnswer').innerHTML='<div class="answer">'+esc(r.answer)+'</div>';el.disabled=false}
if(a==='reverse-matches'){const matches=await Promise.all(state.clients.filter(c=>c.role!=='Propietario').map(async c=>{const r=await api('/api/matches/'+encodeURIComponent(c.id));return {c,m:r.matches.find(m=>m.property.id===id)}}));$('#reverseMatches').innerHTML=matches.filter(x=>x.m&&x.m.score>=50).sort((a,b)=>b.m.score-a.m.score).map(x=>`<a class="person-row" href="#clientes/${esc(x.c.id)}"><div><h3>${esc(x.c.name)}</h3><p>${x.m.score}% de criterios · ${esc(x.m.reasons.join(', '))}</p></div>${icon('arrow')}</a>`).join('')||'<p class="notice">Todavía no hay clientes con suficientes preferencias compatibles.</p>'}
if(a==='generate-sheet')await generateSheet();if(a==='generate-local-sheet')await generateSheet(true);if(a==='save-draft'){if(recorder?.state==='recording'||uploading)throw Error('Detené la grabación y esperá a que se guarde.');await persistVisit();toast('Borrador guardado. Podés continuar después.')}
if(a==='confirm-visit')await confirmVisit();if(a==='record')await startRecording();if(a==='upload-audio'){if(!$('#recordConsent').checked)throw Error('Confirmá la autorización para conservar esta grabación.');visitDraft.recordingConsentAt=new Date().toISOString();await persistVisit();await uploadFile(visitDraft.id,true)}if(a==='transcribe-file')await transcribeFile();if(a==='upload')await uploadFile(id);
if(a==='visit-example'){$('#visitTranscript').value='El cliente busca un departamento con dos dormitorios y estacionamiento. Su presupuesto es hasta 90 mil dólares. Le gustó la ubicación y la luz natural, pero necesita confirmar los gastos comunes. Preguntó si se aceptan mascotas. Acordamos enviar el detalle de expensas y llamar mañana para coordinar una segunda visita. Expresó interés alto.';toast('Ejemplo de conversación. Podés editarlo antes de generar la hoja.')}
if(a==='print')window.print();if(a==='whatsapp')await whatsappModal(id);if(a==='wa-open'){const c=client(id),phone=String(c.phone||'').replace(/\D/g,'');if(!phone)throw Error('Agregá el teléfono del cliente con código de país en su ficha.');window.open('https://wa.me/'+phone+'?text='+encodeURIComponent($('#whatsappMessage').value),'_blank','noopener')}
if(a==='wa-send'){const message=$('#whatsappMessage').value;if(!confirm('¿Enviar este mensaje a '+client(id).name+'?\n\n'+message))return;await api('/api/whatsapp',{method:'POST',body:JSON.stringify({clientId:id,message})});closeModal();toast('Mensaje enviado.')}
if(a==='export-data'){const data=await api('/api/export');download('nexo-respaldo-'+today()+'.json',JSON.stringify(data,null,2));toast('Datos exportados. Los archivos adjuntos se respaldan desde el servidor.')}
if(a==='export-calendar'){download('nexo-agenda.ics',calendarText(),'text/calendar');toast('Calendario descargado. Podés importarlo en Google Calendar.')}
if(a==='reconnect'){el.disabled=true;try{await bootTeam();document.getElementById('connectionIssue')?.remove();if(!(recorder?.state==='recording')&&!uploading)startPage();toast('Conexión recuperada. Verificá tus datos antes de repetir una acción.')}finally{if(el.isConnected)el.disabled=false}}
if(a==='verify-openai'){el.disabled=true;try{const result=await api('/api/ai-check',{method:'POST'});toast(result.message)}finally{el.disabled=false}}
if(a==='notifications'){if(!('Notification' in window))throw Error('Este navegador no admite avisos.');const perm=await Notification.requestPermission();if(perm==='granted'){sessionStorage.setItem('nexo-notifications','1');toast('Avisos activados mientras la aplicación está abierta.')}else toast('El navegador no habilitó los avisos.',true)}
}catch(err){toast(err.message,true);if(el.isConnected)el.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&modal){const fs=$$('button,a[href],input,select,textarea',modal).filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===fs[0]){e.preventDefault();fs.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===fs.at(-1)){e.preventDefault();fs[0]?.focus()}}});
$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#notificationButton').innerHTML=icon('bell');$('#notificationButton').onclick=()=>location.hash='#agenda';$('#profile').onclick=()=>location.hash='#perfil';$('#topDate').textContent=new Date().toLocaleDateString('es-BO',{weekday:'short',day:'numeric',month:'long'});
