setInterval(()=>{if(sessionStorage.getItem('nexo-notifications')!=='1'||!('Notification' in window)||Notification.permission!=='granted')return;state.events.filter(e=>e.status==='Pendiente'&&Math.abs(new Date(e.date)-Date.now())<60000).forEach(e=>{const key='nexo-notified-'+e.id;if(!sessionStorage.getItem(key)){new Notification('Nexo · '+e.title,{body:client(e.clientId).name||'Actividad del equipo',icon:'/mark.svg'});sessionStorage.setItem(key,'1')}})},30000);
